policy:
{
  // Build a realistic 3-tier policy from the checks alone:
  //   - anyone (autogroup:member) reaches tag:web on 443
  //   - tag:web reaches tag:db on 5432
  //   - engineers get check-SSH to tag:web (autogroup:nonroot)
  //   - nothing else is open
  "groups": {
    "group:eng": ["alice@example.com", "bob@example.com"],
  },
  "tagOwners": {
    "tag:web": ["group:eng"],
    "tag:db": ["group:eng"],
  },
  "grants": [
    // TODO
  ],
  "ssh": [
    // TODO
  ],
  "tests": [
    { "src": "carol@example.com", "accept": ["tag:web:443"], "deny": ["tag:db:5432", "tag:web:22"] },
    { "src": "tag:web", "accept": ["tag:db:5432"], "deny": ["tag:db:22"] },
  ],
  "sshTests": [
    { "src": "alice@example.com", "dst": ["tag:web"], "check": ["ubuntu"] },
  ],
}
